<template>
<section class="space-y-8"><div><p class="font-bold text-indigo-600">MANAGEMENT</p><h1 class="mt-2 text-4xl font-black">Catalog & inventory</h1><p class="mt-2 text-slate-500">Company-owned products, configurable attributes, brands, warehouses, suppliers and stock.</p></div>
<div class="flex flex-wrap gap-2 border-b pb-3"><button v-for="t in tabs" :key="t" @click="tab=t" :class="['rounded-xl px-4 py-2 text-sm font-bold',tab===t?'bg-slate-950 text-white':'bg-white border']">{{t}}</button></div>
<div v-if="tab==='Product'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Create product</h2><div class="mt-5 grid gap-4 md:grid-cols-2"><input v-model="form.name" class="rounded-xl border p-3" placeholder="Product name"/><select v-model="form.categoryId" @change="loadCategoryAttributes" class="rounded-xl border p-3"><option value="">Category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="form.brandId" class="rounded-xl border p-3"><option value="">Brand (optional)</option><option v-for="b in brands" :key="b.id" :value="b.id">{{b.name}}</option></select><input v-model.number="form.price" type="number" class="rounded-xl border p-3" placeholder="Base price"/><input v-model="form.sku" class="rounded-xl border p-3" placeholder="Base SKU"/><input v-model="form.imageUrl" class="rounded-xl border p-3" placeholder="Image URL"/></div><textarea v-model="form.description" class="mt-4 w-full rounded-xl border p-3" rows="3" placeholder="Description"></textarea>
<div class="mt-7 rounded-2xl bg-slate-50 p-4"><h3 class="font-black">Category attributes</h3><p class="text-xs text-slate-500">Only attributes assigned to this category appear here.</p><div v-for="o in optionForms" :key="o.attributeId" class="mt-4 rounded-xl border bg-white p-4"><div class="flex items-center gap-3"><b>{{o.name}}</b><label class="ml-auto text-sm"><input type="checkbox" v-model="o.isVariant"/> Use for variants</label></div><div class="mt-3 flex flex-wrap gap-2"><button v-for="v in o.values" :key="v.id" @click="toggleValue(o,v.id)" :class="['rounded-lg border px-3 py-2 text-sm font-bold',o.selected.includes(v.id)?'border-indigo-600 bg-indigo-50 text-indigo-700':'bg-white']">{{v.label||v.value}}</button></div><p v-if="!o.values.length" class="mt-2 text-xs text-amber-600">Add values to this attribute first.</p></div><p v-if="!optionForms.length" class="mt-3 text-sm text-slate-400">Select a category with assigned attributes.</p></div>
<div class="mt-7 flex items-center justify-between"><h3 class="font-black">Variants</h3><button @click="generateVariants" class="rounded-xl border px-4 py-2 font-bold">Generate combinations</button></div><div v-if="variants.length" class="mt-3 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-2">Options</th><th class="p-2">SKU</th><th class="p-2">Price</th><th class="p-2">Warehouse</th><th class="p-2">Opening stock</th></tr></thead><tbody><tr v-for="(v,i) in variants" :key="i" class="border-b"><td class="p-2 font-semibold">{{v.label}}</td><td class="p-2"><input v-model="v.sku" class="w-32 rounded border p-2"/></td><td class="p-2"><input v-model.number="v.price" type="number" class="w-28 rounded border p-2"/></td><td class="p-2"><select v-model="v.warehouseId" class="rounded border p-2"><option value="">Select</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select></td><td class="p-2"><input v-model.number="v.quantity" type="number" min="0" class="w-24 rounded border p-2"/></td></tr></tbody></table></div><button @click="createProduct" :disabled="busy" class="mt-6 rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white disabled:opacity-50">{{busy?'Saving…':'Create product & variants'}}</button><p v-if="message" class="mt-3 text-sm">{{message}}</p></div>
<div v-if="tab==='Attributes'" class="grid gap-6 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Create attribute</h2><div class="mt-4 space-y-3"><input v-model="attributeForm.name" class="w-full rounded-xl border p-3" placeholder="Attribute name, e.g. Color"/><select v-model="attributeForm.type" class="w-full rounded-xl border p-3"><option value="select">Select</option><option value="color">Color</option><option value="text">Text</option><option value="number">Number</option><option value="boolean">Boolean</option></select><input v-model="attributeForm.values" class="w-full rounded-xl border p-3" placeholder="Values, e.g. Black, White, Red"/><button @click="createAttribute" class="w-full rounded-xl bg-slate-950 py-3 font-bold text-white">Create attribute</button></div></div><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Assign to category</h2><div class="mt-4 space-y-3"><select v-model="assignment.categoryId" class="w-full rounded-xl border p-3"><option value="">Category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="assignment.attributeId" class="w-full rounded-xl border p-3"><option value="">Attribute</option><option v-for="a in attributes" :key="a.id" :value="a.id">{{a.name}}</option></select><label class="block text-sm"><input type="checkbox" v-model="assignment.isRequired"/> Required</label><label class="block text-sm"><input type="checkbox" v-model="assignment.isVariant"/> Variant option</label><button @click="assignAttribute" class="w-full rounded-xl bg-indigo-600 py-3 font-bold text-white">Assign attribute</button></div><div class="mt-5 space-y-2"><div v-for="a in attributes" :key="a.id" class="rounded-xl bg-slate-50 p-3"><b>{{a.name}}</b><p class="text-xs text-slate-500">{{a.type}} · {{a.values?.length||0}} values</p></div></div></div></div>
<div v-if="tab==='Inventory'" class="grid gap-6 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Stock movement</h2><div class="mt-4 space-y-3"><select v-model="adjust.warehouseId" class="w-full rounded-xl border p-3"><option value="">Warehouse</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><select v-model="adjust.variantId" class="w-full rounded-xl border p-3"><option value="">Product variant</option><option v-for="v in allVariants" :key="v.id" :value="v.id">{{v.product?.name}} · {{v.sku}}</option></select><select v-model="adjust.type" class="w-full rounded-xl border p-3"><option value="receive">Receive stock</option><option value="adjustment_in">Adjustment in</option><option value="adjustment_out">Adjustment out</option><option value="damage">Damage</option><option value="return">Customer return</option></select><input v-model.number="adjust.quantity" type="number" min="1" class="w-full rounded-xl border p-3" placeholder="Quantity"/><input v-model="adjust.note" class="w-full rounded-xl border p-3" placeholder="Reason / note"/><button @click="adjustStock" class="w-full rounded-xl bg-slate-950 py-3 font-bold text-white">Save movement</button></div></div><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Current inventory</h2><div class="mt-4 space-y-2"><div v-for="x in inventory" :key="x.id" class="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><b>{{x.variant?.product?.name}}</b><p class="text-xs text-slate-500">{{x.variant?.sku}} · {{x.warehouse?.name}}</p></div><div class="text-right"><b>{{x.quantityOnHand}}</b><p class="text-xs text-slate-500">available {{Number(x.quantityOnHand)-Number(x.reservedQuantity)}}</p></div></div></div></div></div>
<div v-if="tab==='Brands'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Brands</h2><div class="mt-4 flex gap-3"><input v-model="brandName" class="flex-1 rounded-xl border p-3" placeholder="Brand name"/><button @click="createBrand" class="rounded-xl bg-slate-950 px-5 font-bold text-white">Add brand</button></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="b in brands" :key="b.id" class="rounded-full bg-slate-100 px-3 py-2 text-sm font-bold">{{b.name}}</span></div></div>
<div v-if="tab==='Warehouses'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Warehouses</h2><div class="mt-4 grid gap-3 md:grid-cols-3"><input v-model="warehouseForm.code" class="rounded-xl border p-3" placeholder="Code"/><input v-model="warehouseForm.name" class="rounded-xl border p-3" placeholder="Warehouse name"/><input v-model="warehouseForm.city" class="rounded-xl border p-3" placeholder="City"/></div><button @click="createWarehouse" class="mt-3 rounded-xl bg-slate-950 px-5 py-3 font-bold text-white">Add warehouse</button><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="w in warehouses" :key="w.id" class="rounded-xl border p-4"><b>{{w.name}}</b><p class="text-sm text-slate-500">{{w.code}} · {{w.city||'No city'}}</p></div></div></div>
<div v-if="tab==='Suppliers'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Suppliers</h2><div class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="supplierForm.name" class="rounded-xl border p-3" placeholder="Supplier name"/><input v-model="supplierForm.contactName" class="rounded-xl border p-3" placeholder="Contact person"/><input v-model="supplierForm.phone" class="rounded-xl border p-3" placeholder="Phone"/><input v-model="supplierForm.email" class="rounded-xl border p-3" placeholder="Email"/></div><button @click="createSupplier" class="mt-3 rounded-xl bg-slate-950 px-5 py-3 font-bold text-white">Add supplier</button><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="s in suppliers" :key="s.id" class="rounded-xl border p-4"><b>{{s.name}}</b><p class="text-sm text-slate-500">{{s.contactName||'No contact'}} · {{s.phone||'No phone'}}</p></div></div></div>
</section></template>
<script>import api from'../services/api';export default{data(){return{tab:'Product',tabs:['Product','Attributes','Inventory','Brands','Warehouses','Suppliers'],categories:[],brands:[],warehouses:[],suppliers:[],attributes:[],allVariants:[],inventory:[],optionForms:[],variants:[],brandName:'',message:'',busy:false,attributeForm:{name:'',type:'select',values:''},assignment:{categoryId:'',attributeId:'',isRequired:false,isVariant:false},form:{name:'',categoryId:'',brandId:'',price:0,sku:'',imageUrl:'',description:'',status:'active'},warehouseForm:{code:'',name:'',city:''},supplierForm:{name:'',contactName:'',phone:'',email:''},adjust:{warehouseId:'',variantId:'',type:'receive',quantity:1,note:''}}},async mounted(){await this.load()},methods:{async load(){const [c,b,w,s,a,i]=await Promise.all([api.get('/categories'),api.get('/brands'),api.get('/warehouses'),api.get('/suppliers'),api.get('/attributes'),api.get('/inventory')]);this.categories=c.data.data||[];this.brands=b.data.data||[];this.warehouses=w.data.data||[];this.suppliers=s.data.data||[];this.attributes=a.data.data||[];this.inventory=i.data.data||[];const ps=await api.get('/products',{params:{limit:100}});this.allVariants=(ps.data.data||[]).flatMap(p=>(p.variants||[]).map(v=>({...v,product:p})))},async loadCategoryAttributes(){this.optionForms=[];if(!this.form.categoryId)return;const r=await api.get('/attributes/categories/'+this.form.categoryId);this.optionForms=(r.data.data||[]).map(x=>({attributeId:x.attribute.id,name:x.attribute.name,values:x.attribute.values||[],selected:[],isVariant:x.isVariant}))},toggleValue(o,id){o.selected=o.selected.includes(id)?o.selected.filter(x=>x!==id):[...o.selected,id]},generateVariants(){const groups=this.optionForms.filter(x=>x.isVariant&&x.selected.length).map(x=>({attributeId:x.attributeId,name:x.name,values:x.values.filter(v=>x.selected.includes(v.id))}));let combos=[[]];for(const g of groups)combos=combos.flatMap(c=>g.values.map(v=>[...c,{attributeId:g.attributeId,value:v}]));this.variants=combos.map((combo,i)=>({label:combo.map(x=>x.value.label||x.value.value).join(' / ')||'Default',sku:(this.form.sku||'SKU')+'-'+String(i+1).padStart(3,'0'),price:Number(this.form.price||0),warehouseId:this.warehouses[0]?.id||'',quantity:0,options:combo.map(x=>({attributeId:x.attributeId,attributeValueId:x.value.id}))}))},async createProduct(){this.message='';this.busy=true;try{const attrPayload=this.optionForms.flatMap(o=>o.selected.map(id=>({attributeId:o.attributeId,attributeValueId:id})));const variants=this.variants.length?this.variants:[{sku:this.form.sku||'SKU-'+Date.now().toString(36),price:this.form.price,options:[],inventory:this.warehouses[0]?[{warehouseId:this.warehouses[0].id,quantity:0}]:[]}];for(const v of variants)v.inventory=v.warehouseId?[{warehouseId:v.warehouseId,quantity:Number(v.quantity||0)}]:[];await api.post('/products',{...this.form,attributeValues:attrPayload,variants});this.message='Product created successfully.';this.form={name:'',categoryId:'',brandId:'',price:0,sku:'',imageUrl:'',description:'',status:'active'};this.variants=[];await this.load()}catch(e){this.message=e.response?.data?.message||'Unable to create product'}finally{this.busy=false}},async createAttribute(){if(!this.attributeForm.name)return;await api.post('/attributes',{name:this.attributeForm.name,type:this.attributeForm.type,values:this.attributeForm.values.split(',').map(value=>({value:value.trim(),label:value.trim()})).filter(x=>x.value)});this.attributeForm={name:'',type:'select',values:''};await this.load()},async assignAttribute(){await api.post('/attributes/categories/'+this.assignment.categoryId,this.assignment);this.assignment={categoryId:'',attributeId:'',isRequired:false,isVariant:false};await this.load()},async createBrand(){if(!this.brandName)return;await api.post('/brands',{name:this.brandName});this.brandName='';await this.load()},async createWarehouse(){await api.post('/warehouses',this.warehouseForm);this.warehouseForm={code:'',name:'',city:''};await this.load()},async createSupplier(){await api.post('/suppliers',this.supplierForm);this.supplierForm={name:'',contactName:'',phone:'',email:''};await this.load()},async adjustStock(){try{await api.post('/inventory/adjust',this.adjust);this.adjust={...this.adjust,quantity:1,note:''};await this.load()}catch(e){this.message=e.response?.data?.message||'Unable to update inventory'}}}}</script>